#include <iostream>

int main()
{
    int n{};
    if (!(std::cin >> n)) return 0;

    for (int i = 1; i <= n; ++i)
    {
        for (int j = 1; j <= n; ++j)
        {
            if (j > 1) std::cout << ' ';
            std::cout << i * j;
        }
        std::cout << "\n";
    }

    return 0;
}
